CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,role VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id BIGSERIAL PRIMARY KEY,name VARCHAR(180) NOT NULL,description TEXT,status VARCHAR(30) DEFAULT 'ON_TRACK',priority VARCHAR(20) DEFAULT 'MEDIUM',owner_id BIGINT REFERENCES users(id),start_date DATE,end_date DATE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks(id BIGSERIAL PRIMARY KEY,project_id BIGINT REFERENCES projects(id),title VARCHAR(220) NOT NULL,assignee_id BIGINT REFERENCES users(id),status VARCHAR(30),priority VARCHAR(20),progress_percent INT CHECK(progress_percent BETWEEN 0 AND 100),start_date DATE,due_date DATE,estimated_hours NUMERIC,actual_hours NUMERIC,blocked BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS task_dependencies(id BIGSERIAL PRIMARY KEY,predecessor_task_id BIGINT REFERENCES tasks(id),successor_task_id BIGINT REFERENCES tasks(id),dependency_type VARCHAR(30) DEFAULT 'FINISH_TO_START');
CREATE TABLE IF NOT EXISTS activity_logs(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),project_id BIGINT REFERENCES projects(id),action VARCHAR(120),entity_type VARCHAR(50),entity_id BIGINT,old_value TEXT,new_value TEXT,timestamp TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_scores(id BIGSERIAL PRIMARY KEY,project_id BIGINT REFERENCES projects(id),task_id BIGINT REFERENCES tasks(id),score NUMERIC,risk_level VARCHAR(20),reason TEXT,calculated_at TIMESTAMPTZ DEFAULT now());
